use vstd::prelude::*;

verus! {

spec fn bitand_u8(x: u8, y: u8) -> u8 { x & y }

fn bitwise_and(a: Vec<u8>, b: Vec<u8>) -> (res: Vec<u8>)
    requires
        a@.len() == b@.len(),
    ensures
        res@.len() == a@.len(),
        forall|i: int|
            0 <= i < a@.len() ==> res@[i] == bitand_u8(a@[i], b@[i]),
{
    assert_eq!(a.len(), b.len(), "input vectors must have the same length");

    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| x & y)
        .collect()
}

} // verus!

